  "choices": [{ "text": "选项文本", "hint": "可选的风险或代价提示" }],
  "ops": [{ "adjust": "键", "by": 1 }, { "flag": "标记" }, { "add": "物品名" }, { "set": "键", "value": 12 }],
  "npc": [{ "key": "npc_id", "affinity": 3, "relation": "关系变化", "met": true, "notes": "状态" }],
  "items": [{ "name": "物品名", "kind": "分类（可省）", "origin": "怎么得到的", "use": "已知用途", "possible": "可能的用途（还没验证）", "abilities": "效果与能力（可省）", "stats": "属性（可省）", "limits": "限制与代价（可省）", "customizable": [{ "label": "该由玩家定的项", "value": "你的初稿", "hint": "说明" }] }],
  "memory": ["此后必须一直记得的事实"],
  "scene": "场景名",
